public class Song {
    private String title;
    private String artist;
    private String genre;
    private int energyLevel;

    public Song(String title, String artist, String genre, int energyLevel) {
        this.title = title;
        this.artist = artist;
        this.genre = genre;
        this.energyLevel = energyLevel;
    }

    public String getTitle() {
        return title;
    }

    public String getArtist() {
        return artist;
    }

    public String getGenre() {
        return genre;
    }

    public int getEnergyLevel() {
        return energyLevel;
    }

    @Override
    public String toString() {
        return title + " by " + artist + " (" + genre + ", energy " + energyLevel + ")";
    }
}
